function tourVisible(){return !$('#tour').classList.contains('hidden')}
function positionTour(){if(!tourVisible())return;const card=$('#tour .tourCard'),spot=$('#tour .tourSpotlight'),vw=window.innerWidth,vh=window.innerHeight;const r=tourTarget?.getBoundingClientRect();const visible=r&&r.width&&r.height;const rect=visible?{left:r.left,top:r.top,right:r.right,bottom:r.bottom,width:r.width,height:r.height}:{left:vw/2,top:vh/2,right:vw/2,bottom:vh/2,width:0,height:0};card.style.width=Math.min(380,Math.max(1,vw-32))+'px';const size=card.getBoundingClientRect(),p=placeTourCard(rect,{width:vw,height:vh},{width:size.width,height:size.height});card.style.left=p.left+'px';card.style.top=p.top+'px';card.dataset.placement=visible?p.placement:'center';card.style.setProperty('--tour-arrow',p.arrow+'px');card.style.visibility='visible';const pointer=$('#tour .tourPointer');pointer.hidden=!visible||p.placement==='center';if(!pointer.hidden){pointer.style.left=(p.placement==='right'?p.left-6:p.placement==='left'?p.left+p.width-6:p.left+p.arrow-6)+'px';pointer.style.top=(p.placement==='bottom'?p.top-6:p.placement==='top'?p.top+p.height-6:p.top+p.arrow-6)+'px'}spot.hidden=!visible;if(visible){spot.style.left=Math.max(4,r.left-5)+'px';spot.style.top=Math.max(4,r.top-5)+'px';spot.style.width=Math.max(0,Math.min(vw-4,r.right+5)-Math.max(4,r.left-5))+'px';spot.style.height=Math.max(0,Math.min(vh-4,r.bottom+5)-Math.max(4,r.top-5))+'px'}}
function scheduleTour(){cancelAnimationFrame(tourFrame);tourFrame=requestAnimationFrame(positionTour)}
function startTour(force=false){if(!force&&profileData.tutorialCompleted)return;if(tourVisible())return;tourReturn={...historySnapshot()};tourMode=state.mode;tourIndex=0;const root=$('#tour'),card=$('#tour .tourCard');if(!$('.tourSpotlight'))root.insertAdjacentHTML('afterbegin','<div class="tourSpotlight" aria-hidden="true"></div><div class="tourPointer" aria-hidden="true" hidden></div>');root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-labelledby','tourTitle');card.setAttribute('tabindex','-1');$('#tourStep').setAttribute('aria-live','polite');$('#tourSkip').textContent='Salir del tutorial';root.classList.remove('hidden');paintTour();card.focus({preventScroll:true})}
function paintTour(){const steps=tourByMode[tourMode],step=steps[tourIndex];$('#tour .tourCard').style.visibility='hidden';navigateApp({mode:tourMode,section:step.section},{replace:true});$('#tourStep').innerHTML=`<span class="tourProgress">${tourMode==='personal'?'Personal':'Negocio'} · Paso ${tourIndex+1} de ${steps.length}</span><h2 id="tourTitle">${step.title}</h2><p>${step.copy}</p>`;$('#tourPrev').style.visibility=tourIndex?'visible':'hidden';$('#tourPrev').disabled=tourIndex===0;$('#tourNext').textContent=tourIndex===steps.length-1?'Terminar':'Siguiente';tourTarget=[...document.querySelectorAll('#content '+step.target)].find(e=>e.getClientRects().length)||document.querySelector('#content');requestAnimationFrame(()=>{if(!tourVisible())return;tourTarget?.scrollIntoView({block:'center',behavior:'instant'});scheduleTour();requestAnimationFrame(()=>{if(tourVisible())$('#tourNext').focus({preventScroll:true})})})}
async function finishTour(){if(tourFinishing)return;tourFinishing=true;try{profileData=await commitProfile(profileData,{tutorialCompleted:true},cloud.saveProfile)}catch(e){showCloudError(e)}finally{tourFinishing=false;$('#tour').classList.add('hidden');cancelAnimationFrame(tourFrame);tourTarget=null;if(tourReturn)navigateApp(tourReturn,{replace:true});tourReturn=null;(()=>{const focus=$('#restartTour')||$('#pageTitle');if(focus?.tagName==='H1')focus.setAttribute('tabindex','-1');focus?.focus({preventScroll:true})})()}}
$('#tourNext').onclick=()=>{if(tourIndex===tourByMode[tourMode].length-1)finishTour();else{tourIndex++;paintTour()}};$('#tourPrev').onclick=()=>{tourIndex=Math.max(0,tourIndex-1);paintTour()};$('#tourSkip').onclick=finishTour;
window.addEventListener('resize',scheduleTour);document.addEventListener('scroll',()=>{if(tourVisible())scheduleTour()},{capture:true,passive:true});
document.addEventListener('keydown',e=>{if(!tourVisible())return;if(e.key==='Escape'){e.preventDefault();finishTour();return}if(e.key!=='Tab')return;const buttons=[$('#tourSkip'),$('#tourPrev'),$('#tourNext')].filter(b=>!b.disabled&&getComputedStyle(b).visibility!=='hidden'),first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&(document.activeElement===first||!buttons.includes(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!buttons.includes(document.activeElement))){e.preventDefault();first.focus()}});


