const ownsSnapshot=snapshot=>!!snapshot?.userId&&snapshot.userId===syncOwner&&snapshot.userId===cloud.session()?.user?.id;
let syncTimer=null,syncPromise=Promise.resolve(),syncPending=false,syncRetryTimer=null;
function syncSnapshot(){return ensureSyncId({userId:syncOwner,records:JSON.parse(JSON.stringify(records)),profile:{...profileData}})}
function showSyncState(kind,text){
  document.querySelectorAll('.syncError,.syncStatus').forEach(x=>x.remove());
  const c=$('#content');if(!c)return;
  c.insertAdjacentHTML('afterbegin',`<div class="${kind==='error'?'syncError':'syncStatus'}">${text}</div>`);
}
function persistPending(snapshot){try{const normalized=ensureSyncId(snapshot);if(!normalized.userId)return normalized;localStorage.setItem(pendingKey(normalized.userId),JSON.stringify(normalized));return normalized}catch{return ensureSyncId(snapshot)}}
function clearPending(snapshot){try{const pending=readPending();if(samePendingSnapshot(pending,snapshot)){localStorage.removeItem(pendingKey(snapshot.userId));return true}}catch{}return false}
function readPending(){try{if(!syncOwner||cloud.session()?.user?.id!==syncOwner)return null;const raw=JSON.parse(localStorage.getItem(pendingKey(syncOwner))||'null');if(!raw||raw.userId!==syncOwner)return null;return ensureSyncId(raw)}catch{return null}}
async function flushRecords(snapshot=syncSnapshot()){
  if(!ownsSnapshot(snapshot))return false;
  snapshot=persistPending(snapshot);syncPending=true;
  try{
    await cloud.syncRecords(snapshot.records,snapshot.profile,snapshot.userId);
    const cleared=clearPending(snapshot);
    syncPending=!!readPending();
    clearTimeout(syncRetryTimer);
    if(cleared&&!syncPending)document.querySelectorAll('.syncError,.syncStatus').forEach(x=>x.remove());
    return true;
  }catch(e){
    syncPending=true;showCloudError(e);
    clearTimeout(syncRetryTimer);
    if(navigator.onLine&&ownsSnapshot(snapshot))syncRetryTimer=setTimeout(()=>queueSync(readPending()||snapshot,0),3000);
    return false;
  }
}
function queueSync(snapshot=syncSnapshot(),delay=180){
  if(!ownsSnapshot(snapshot))return;
  snapshot=persistPending(snapshot);clearTimeout(syncTimer);
  syncTimer=setTimeout(()=>{syncPromise=syncPromise.then(()=>flushRecords(snapshot))},delay);
}
const saveRecords=()=>queueSync(syncSnapshot(),180);
function showCloudError(e){console.error(e);showSyncState('error',navigator.onLine?'No pudimos guardar todavía. FINORVE conservará los cambios y reintentará automáticamente.':'Sin conexión. Tus cambios quedan pendientes y se guardarán al volver a estar en línea.')}
window.addEventListener('online',()=>{const pending=readPending();if(pending)queueSync(pending,50)});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){const pending=readPending();if(pending)queueSync(pending,50)}});
window.addEventListener('pagehide',()=>{const pending=syncPending?readPending():null;if(pending)persistPending(pending)});
const bucket=()=>records[state.mode]||(records[state.mode]={});
function listFor(type){return bucket()[type]||(bucket()[type]=[])}
function currency(){return state.mode==='personal'?profileData.personalCurrency:profileData.businessCurrency}
function recordView(){const type=sectionType[state.section];const t=titles[state.section];const list=listFor(type);const entity=entitySections.has(state.section);const total=list.filter(x=>(x.currency||'USD')===currency()).reduce((a,x)=>a+(type==='saving'&&isWithdrawal(x)?-1:1)*(Number.isSafeInteger(x.amountMinor)?x.amountMinor:Math.round(Number(x.amount||0)*10**CURRENCY_MINOR_UNITS[x.currency||'USD'])),0);const totalLabel=state.section==='debts'?'SALDO TOTAL':state.section==='assets'?'VALOR TOTAL':state.section==='goals'?'OBJETIVO TOTAL':type==='saving'?'AHORRO NETO REGISTRADO':'TOTAL REGISTRADO';return `<div class="sectionHead"><div><span class="eyebrow">FINORVE · ${state.mode==='personal'?'PERSONAL':'NEGOCIO'}</span><h2>${t}</h2><p>${entity?'Añade cada elemento una sola vez y actualiza su valor cuando cambie.':state.mode==='personal'?'Registra tus datos reales. FINORVE actualizará tu panorama automáticamente.':'Registra datos reales del negocio y mantenlos separados de cualquier simulación.'}</p></div><button class="primary" id="newRecord">＋ ${entity?'Nuevo':'Añadir'}</button></div><div class="recordSummary"><div><small>${totalLabel}</small><strong>${moneyMinor(total,currency())}</strong></div><div><small>${entity?'ELEMENTOS':'MOVIMIENTOS'}</small><strong>${list.length}</strong></div><div><small>TIPO</small><strong>${state.mode==='personal'?'Personal':'Negocio'}</strong></div></div><div class="card recordListCard"><div class="recordListHead"><div><span class="eyebrow">${entity?'POSICIÓN ACTUAL':'HISTORIAL'}</span><h3>${t}</h3></div><small>${list.length?(entity?'Actualiza sin duplicar':'Últimos registros'):'Sin registros todavía'}</small></div><div class="list">${list.length?list.map((x,i)=>`<div class="row recordRow"><div class="ico">${state.mode==='personal'?'○':'▣'}</div><div><b>${esc(x.name)}</b><small>${x.date||localDateKey()} · ${x.demo?'Demostración':'Real'}${entity?' · '+(entityLabel[state.section]||'valor')+' actual':''}${state.mode==='personal'&&type==='expense'?' · '+(EXPENSE_TYPES[x.expenseClass]?.label||'Sin clasificar'):state.mode==='personal'&&type==='saving'?' · '+(personalFunds().find(f=>f.id===x.fundId)?.name||'Sin fondo asignado')+' · '+(isWithdrawal(x)?'Retirada':'Aporte'):''}</small></div><div class="amount">${moneyMinor(Number.isSafeInteger(x.amountMinor)?x.amountMinor:Math.round(Number(x.amount||0)*10**CURRENCY_MINOR_UNITS[x.currency||'USD']),x.currency||'USD')} <button class="ghost editRecord" data-i="${i}">Editar</button><button class="ghost deleteRecord" data-i="${i}" aria-label="Eliminar">×</button></div></div>`).join(''):`<div class="emptyState"><span>＋</span><h3>Aún no hay registros</h3><p>${entity?'Crea el primero. Después podrás actualizar su valor sin añadir duplicados.':'Añade el primero para que FINORVE empiece a construir tu panorama.'}</p><button class="primary" id="newRecordEmpty">Añadir primer registro</button></div>`}</div></div>`}
function home(){return state.mode==='personal'?personalHome()+upcomingCard():businessDashboard()+upcomingCard()}
function planView(){return state.mode==='personal'?foundationView():businessOrganize()}
function generic(){if(state.section==='calendar')return calendarView();if(state.mode==='business'&&['results','breakEven'].includes(state.section))return businessDashboard();if(state.mode==='business'&&state.section==='movements')return businessDayView();if(state.mode==='personal'&&state.section==='expenses')return expenseView();if(state.mode==='personal'&&state.section==='goals')return foundationView();if(state.section==='movements')return movementsView();if(state.section==='plan')return planView();if(state.section==='decisions')return decisions();if(state.section==='more')return moreView();if(state.section==='profile')return profile();if(state.section==='settings')return settings();if(state.section==='breakEven')return breakEven();if(state.section==='cashflow')return cashflowView();if(state.section==='results')return resultsView();if(state.section==='diagnostic')return diagnosticView();if(sectionType[state.section])return recordView();return moreView()}
function cashflowView(){const b=records.business||{};const rows=[...(b.collection||[]).map((x,i)=>({...x,_type:'collection',_i:i,_label:'Cobro'})),...(b.cashPayment||[]).map((x,i)=>({...x,_type:'cashPayment',_i:i,_label:'Pago'})),...(b.debtPrincipal||[]).map((x,i)=>({...x,_type:'debtPrincipal',_i:i,_label:'Capital deuda'})),...(b.debtInterest||[]).map((x,i)=>({...x,_type:'debtInterest',_i:i,_label:'Interés deuda'}))].sort((a,b)=>(b.date||'').localeCompare(a.date||''));const totalIn=(b.collection||[]).filter(x=>(x.currency||'USD')===currency()).reduce((a,x)=>a+asMinor(x),0),totalOut=['cashPayment','debtPrincipal','debtInterest'].reduce((sum,type)=>sum+(b[type]||[]).filter(x=>(x.currency||'USD')===currency()).reduce((a,x)=>a+asMinor(x),0),0);return `<div class="sectionHead"><div><span class="eyebrow">FINORVE · CAJA</span><h2>Flujo de caja</h2><p>Separa el dinero realmente cobrado y pagado de ventas, costos y gastos registrados.</p></div><div class="cashActions"><button class="primary cashAdd" data-cash="collection">＋ Cobro</button><button class="ghost cashAdd" data-cash="cashPayment">− Pago</button></div></div><div class="cashSummary"><div><small>COBRADO</small><strong>+${moneyMinor(totalIn,currency())}</strong></div><div><small>PAGADO</small><strong>−${moneyMinor(totalOut,currency())}</strong></div><div><small>FLUJO NETO</small><strong>${moneyMinor(totalIn-totalOut,currency())}</strong></div></div><div class="card recordListCard"><div class="recordListHead"><div><span class="eyebrow">MOVIMIENTOS DE CAJA</span><h3>Cobros y pagos</h3></div><small>${rows.length} registros</small></div><div class="list">${rows.length?rows.map(x=>`<div class="row recordRow"><div class="ico">${x._label==='Cobro'?'＋':'−'}</div><div><b>${esc(x.name)}</b><small>${x.date} · ${x._label} · ${x.demo?'Demostración':'Real'}</small></div><div class="amount">${x._label==='Cobro'?'+':'−'}${moneyMinor(asMinor(x),x.currency||'USD')} <button class="ghost deleteCash" data-type="${x._type}" data-i="${x._i}" aria-label="Eliminar">×</button></div></div>`).join(''):'<div class="emptyState"><span>↕</span><h3>Aún no hay movimientos de caja</h3><p>Registra un cobro o un pago para que FINORVE calcule tu flujo neto.</p></div>'}</div></div>`}
function resultsView(){const m=businessMonth(businessEngineData(),monthKey());const margin=m.sales?Math.round(m.operatingResult*100/m.sales):0;return `<div class="sectionHead"><div><span class="eyebrow">FINORVE · NEGOCIO</span><h2>Resultado</h2><p>Mide el resultado económico del mes sin confundirlo con el efectivo disponible.</p></div></div><div class="resultHero"><div><span class="eyebrow">RESULTADO OPERATIVO</span><h2>${moneyMinor(m.operatingResult,currency())}</h2><p>${m.operatingResult>=0?'El negocio registra resultado positivo en el período.':'El período registra resultado negativo; revisa costos y gastos antes de asumir más estructura.'}</p></div><div class="resultMargin"><small>MARGEN</small><strong>${m.sales?margin+'%':'—'}</strong></div></div><div class="resultGrid"><div><small>VENTAS</small><strong>${moneyMinor(m.sales,currency())}</strong></div><div><small>COSTOS VARIABLES</small><strong>${moneyMinor(m.variableCosts,currency())}</strong></div><div><small>GASTOS OPERATIVOS</small><strong>${moneyMinor(m.operatingExpenses,currency())}</strong></div></div><div class="card resultNote"><span class="eyebrow">IMPORTANTE</span><h3>Resultado no significa caja</h3><p>Una venta puede existir antes de ser cobrada. Usa Flujo de caja para saber cuánto dinero realmente entró o salió.</p><button class="ghost" data-section="cashflow">Ver flujo de caja →</button></div>`}
function diagnosticView(){const m=personalMonth(personalEngineData(),monthKey()),p=personalPosition(personalEngineData(),monthEndKey());const savingsRate=m.savingsRateBp==null?null:(m.savingsRateBp/100).toFixed(1);const liquidityState=m.available>=0?'Estable':'Atención';const wealthState=p.netWorth>=0?'Positivo':'Negativo';return `<div class="sectionHead"><div><span class="eyebrow">FINORVE · DIAGNÓSTICO</span><h2>Diagnóstico financiero</h2><p>Una lectura breve de tu situación actual para saber dónde concentrarte primero.</p></div></div><div class="diagnosticLead"><div class="diagnosticScore"><span class="eyebrow">TU LECTURA DEL MES</span><h3>${m.available>=0?'Tienes margen para decidir':'Tu prioridad es recuperar liquidez'}</h3><p>${m.available>=0?'Tus registros muestran un disponible positivo después de los compromisos del período.':'Las salidas registradas están superando lo que entra; conviene revisar gastos y compromisos antes de asumir algo nuevo.'}</p><button class="primary" data-section="decisions">Ver decisiones →</button></div><div class="diagnosticMetrics"><div><small>LIQUIDEZ</small><strong>${moneyMinor(m.available,currency())}</strong><em>${liquidityState}</em></div><div><small>PATRIMONIO</small><strong>${moneyMinor(p.netWorth,currency())}</strong><em>${wealthState}</em></div><div><small>TASA DE AHORRO</small><strong>${savingsRate==null?'—':savingsRate+'%'}</strong><em>${savingsRate==null?'Sin datos':Number(savingsRate)>=20?'Buena base':'Por debajo de 20%'}</em></div></div></div><div class="diagnosticGrid"><div class="card diagnosticCard"><span class="eyebrow">QUÉ ESTÁ BIEN</span><h3>${m.available>=0?'Tu disponible sigue siendo positivo':'Ya tienes una foto real de tus salidas'}</h3><p>${m.available>=0?'Eso te da espacio para priorizar ahorro, deuda o inversión con más contexto.':'Identificar el desbalance es el primer paso para corregirlo antes de asumir nuevos compromisos.'}</p></div><div class="card diagnosticCard"><span class="eyebrow">QUÉ REVISAR</span><h3>${p.debts>p.assets*.35?'El peso de la deuda sobre tus activos':'La relación entre ahorro y gasto'}</h3><p>${p.debts>p.assets*.35?'Tu deuda registrada representa una parte relevante de tus activos. Revisa prioridades de pago antes de aumentar riesgo.':'Comprueba si tu tasa de ahorro se acerca al objetivo que quieres sostener en el tiempo.'}</p></div></div>`}
function openCashModal(type){const isIn=type==='collection';openModalForm(isIn?'Nuevo cobro':'Nuevo pago',`<div class="formGrid"><div class="field"><label for="rName">Concepto</label><input id="rName" maxlength="80" placeholder="${isIn?'Ej. Factura cobrada':'Ej. Pago proveedor'}"></div><div class="field"><label for="rAmount">Monto (${currency()})</label><input id="rAmount" inputmode="decimal" placeholder="${amountInput(0)}" aria-description="Usa el formato mostrado en el ejemplo, sin separadores de miles"></div><div class="field"><label for="rDate">Fecha</label><input id="rDate" type="date" value="${localDateKey()}"></div></div>`,()=>{const name=$('#rName').value.trim(),amountMinor=toMinor($('#rAmount').value),date=$('#rDate').value;clearModalError();if(name.length<2)return modalError('Escribe un concepto de al menos 2 caracteres.','#rName');if(amountMinor===null||amountMinor<=0)return modalError('Escribe un monto válido mayor que 0.','#rAmount');if(!date)return modalError('Selecciona una fecha.','#rDate');if(readDaily(records.business||{},date,currency()).registered)return modalError('Este día ya está anotado. Edita su resumen en Anotar el día.','#rDate');const b=records.business||(records.business={});(b[type]||(b[type]=[])).push({name,amountMinor,currency:currency(),date,demo:false});saveRecords();$('#modalWrap').classList.add('hidden');render()})}
function profile(){const initials=profileData.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();return `<div class="sectionHead profileIntro"><div><p>Gestiona tu identidad y las preferencias financieras que FINORVE usa en Personal y Negocio.</p></div><button class="primary" id="saveProfile">Guardar cambios</button></div><div class="profileLayout"><div class="card profileIdentity"><div class="profileCard"><div class="profilePhoto" id="photoPreview">${profileData.photoUrl?`<img class="profileAvatarImage" src="${esc(profileData.photoUrl)}" alt="Foto de perfil de ${esc(profileData.name)}">`:`<span class="profileInitials">${esc(initials)}</span>`}<span class="profilePhotoMark" aria-hidden="true">${navIcon('profile')}</span></div><div><span class="eyebrow">CUENTA PRINCIPAL</span><h2>${profileData.name}</h2><p class="sub">${profileData.email||'Correo asociado a tu cuenta'}</p><button class="ghost profilePhotoAction" id="changePhoto">${navIcon('profile')} ${profileData.photoUrl?'Cambiar foto':'Añadir mi foto'}</button><small class="profilePhotoHelp">JPG, PNG o WebP · hasta 2 MB</small><input type="file" id="photoInput" accept="image/jpeg,image/png,image/webp" hidden></div></div><div class="profileMeta"><div><small>PAÍS</small><b>${profileData.country}</b></div><div><small>MONEDA PERSONAL</small><b>${profileData.personalCurrency}</b></div><div><small>MONEDA NEGOCIO</small><b>${profileData.businessCurrency}</b></div></div></div><div class="card profileFormCard"><div class="cardHead"><div><span class="eyebrow">PREFERENCIAS</span><h3>Datos de tu cuenta</h3></div></div><div class="formGrid"><div class="field"><label for="pfName">Nombre</label><input id="pfName" maxlength="120" required autocomplete="name" value="${esc(profileData.name)}"></div><div class="field"><label for="pfEmail">Correo</label><input id="pfEmail" value="${esc(profileData.email)}" disabled></div><div class="field"><label for="pfCountrySearch">Buscar país</label><input id="pfCountrySearch" type="search" autocomplete="off" placeholder="Ej. Estados Unidos, España, Canadá" aria-controls="pfCountry"><label for="pfCountry">País y moneda sugerida</label><select id="pfCountry">${countryOptions(profileData.country)}</select></div><div class="field"><label for="pfPCurrency">Moneda personal</label><select id="pfPCurrency">${!CURRENCIES.includes(profileData.personalCurrency)?`<option value="${esc(profileData.personalCurrency)}" selected>${esc(currencyLabel(profileData.personalCurrency))} · actual</option>`:''}${CURRENCIES.map(x=>`<option value="${x}" ${x===profileData.personalCurrency?'selected':''}>${esc(currencyOptionLabel(x))}</option>`).join('')}</select></div><div class="field"><label for="pfBCurrency">Moneda negocio</label><select id="pfBCurrency">${!CURRENCIES.includes(profileData.businessCurrency)?`<option value="${esc(profileData.businessCurrency)}" selected>${esc(currencyLabel(profileData.businessCurrency))} · actual</option>`:''}${CURRENCIES.map(x=>`<option value="${x}" ${x===profileData.businessCurrency?'selected':''}>${esc(currencyOptionLabel(x))}</option>`).join('')}</select></div></div><div class="profileNote">El país sugiere tu moneda cuando aún no tienes registros. Puedes elegir otra. Los totales incluyen solo la moneda seleccionada; el historial conserva los importes originales, sin convertirlos.</div></div></div>${membershipCard(membershipLicense)}`}
function demoActive(mode){return Object.values(records[mode]||{}).some(a=>(a||[]).some(x=>x.demo))}
function settings(){return `<div class="sectionHead"><div><span class="eyebrow">FINORVE · CONFIGURACIÓN</span><h2>Ajustes</h2><p>Controla apariencia, seguridad y datos sin afectar tus registros financieros.</p></div></div><div class="settingsGrid"><div class="card settingsCard"><div class="settingsTitle"><span class="settingsIcon">◐</span><div><span class="eyebrow">EXPERIENCIA</span><h3>Apariencia y sonido</h3></div></div><div class="settingsRow"><div><b>Modo de color</b><small>Claro, oscuro o según tu dispositivo.</small></div><button class="ghost" id="settingTheme">${themeLabels[state.theme]||'Sistema'}</button></div><div class="settingsRow"><div><b>Sonido al cambiar de espacio</b><small>Un tono breve al pasar entre Personal y Negocio.</small></div><button class="ghost" id="settingSound">${state.sound?'Activado':'Silenciado'}</button></div><div class="settingsRow"><div><b>Recorrido inicial</b><small>Vuelve a ver la guía de FINORVE cuando quieras.</small></div><button class="ghost" id="restartTour">Ver recorrido</button></div></div><div class="card settingsCard"><div class="settingsTitle"><span class="settingsIcon">⌁</span><div><span class="eyebrow">CUENTA</span><h3>Seguridad y datos</h3></div></div><div class="settingsRow"><div><b>Cambiar contraseña</b><small>Actualiza tu acceso. Mínimo 8 caracteres.</small></div><button class="ghost" id="changePassword">Cambiar</button></div><div class="settingsRow"><div><b>Exportar mis datos</b><small>Descarga una copia JSON de tu información y registros.</small></div><button class="ghost" id="exportData">Exportar</button></div><div class="settingsRow dangerRow"><div><b>Eliminar cuenta</b><small>Elimina permanentemente la cuenta y sus datos asociados.</small></div><button class="ghost dangerButton" id="deleteAccount">Eliminar</button></div></div><div class="card settingsCard demoCard"><div class="settingsTitle"><span class="settingsIcon">◇</span><div><span class="eyebrow">EXPLORACIÓN</span><h3>Datos de demostración</h3></div></div><p class="settingsIntro">Úsalos para explorar FINORVE sin tocar tus datos reales. Se identifican por separado.</p>${['personal','business'].map(m=>`<div class="settingsRow"><div><b>${m==='personal'?'Personal':'Negocio'}</b><small>${m==='personal'?'12 meses':'24 meses'} de ejemplo para probar la experiencia.</small></div><button class="ghost demoToggle" data-demo="${m}">${demoActive(m)?'Eliminar demo':'Cargar demo'}</button></div>`).join('')}</div></div>`}
function openRecordModal(index=null,recordSection=state.section){if(state.mode==='business'&&Number.isInteger(index)&&listFor(sectionType[recordSection])[index]?.dailyRecordId){state.businessDate=listFor(sectionType[recordSection])[index].date;navigateApp({section:'movements',mode:'business'});return}if(state.mode==='personal'&&['expenses','savings'].includes(recordSection))return openPersonalMovement(sectionType[recordSection],index);const type=sectionType[recordSection],list=listFor(type),editing=Number.isInteger(index),current=editing?list[index]:null,entity=entitySections.has(recordSection),valueLabel=recordSection==='debts'?'Saldo actual':recordSection==='assets'?'Valor actual':recordSection==='goals'?'Objetivo':'Monto';openModalForm(`${editing?'Actualizar':(['debts','sales'].includes(recordSection)?'Nueva':'Nuevo')} ${{income:'ingreso',expenses:'gasto',savings:'ahorro',debts:'deuda',assets:'activo',goals:'objetivo',sales:'venta',costs:'costo'}[recordSection]||'movimiento'}`,`<div class="formGrid"><div class="field"><label for="rName">Nombre / concepto</label><input id="rName" maxlength="80" placeholder="Ej. ${recordSection==='debts'?'Tarjeta principal':recordSection==='assets'?'Cuenta de ahorro':recordSection==='goals'?'Fondo de emergencia':'Salario'}" value="${current?esc(current.name):''}"></div><div class="field"><label for="rAmount">${valueLabel} (${current?.currency||currency()})</label><input id="rAmount" inputmode="decimal" placeholder="${amountInput(0)}" aria-description="Usa el formato mostrado en el ejemplo, sin separadores de miles" value="${current?amountInput(asMinor(current),current.currency||'USD'):''}"></div><div class="field"><label for="rDate">Fecha</label><input id="rDate" type="date" value="${current?.date||localDateKey()}"></div></div>`,()=>{const name=$('#rName').value.trim(),amountMinor=toMinor($('#rAmount').value,current?.currency||currency()),date=$('#rDate').value;clearModalError();if(name.length<2)return modalError('Escribe un concepto de al menos 2 caracteres.','#rName');if(amountMinor===null||amountMinor<=0)return modalError('Escribe un monto válido mayor que 0.','#rAmount');if(!date)return modalError('Selecciona una fecha.','#rDate');if(state.mode==='business'&&readDaily(records.business||{},date,currency()).registered)return modalError('Este día ya está anotado. Edita su resumen en Anotar el día para evitar duplicarlo.','#rDate');const base={name,amountMinor,currency:current?.currency||currency(),date,demo:false,entityType:type};if(editing){list[index]={...list[index],...base,entityId:list[index].entityId||list[index].id||crypto.randomUUID()}}else{list.push({...base,...(entity?{entityId:crypto.randomUUID()}:{})})}saveRecords();$('#modalWrap').classList.add('hidden');render()})}
function clearModalError(){const msg=$('.modalMsg');msg?.classList.add('hidden');document.querySelectorAll('#modal .fieldError').forEach(x=>x.classList.remove('fieldError'))}
function modalError(message,selector){const msg=$('.modalMsg');if(msg){msg.textContent=message;msg.classList.remove('hidden')}const el=$(selector);el?.classList.add('fieldError');el?.focus();return false}
function openModalForm(title,body,onSave){$('#modal').setAttribute('role','dialog');$('#modal').setAttribute('aria-modal','true');$('#modal').innerHTML=`<button class="ghost modalClose" aria-label="Cerrar">×</button><h2>${title}</h2>${body}<div class="modalMsg hidden" role="alert"></div><div class="modalActions"><button class="ghost modalCancel">Cancelar</button><button class="primary modalSave">Guardar</button></div>`;$('#modalWrap').classList.remove('hidden');$('.modalClose').onclick=$('.modalCancel').onclick=closeModal;$('.modalSave').onclick=onSave;requestAnimationFrame(()=>$('#modal input,#modal select,#modal textarea,.modalSave')?.focus())}
function toggleDemo(mode){records[mode] ||= {}; if(demoActive(mode)){Object.keys(records[mode]).forEach(k=>records[mode][k]=(records[mode][k]||[]).filter(x=>!x.demo))}else{Object.entries(seed[mode]).forEach(([k,arr])=>{records[mode][k] ||= [];arr.forEach(([name,amount],i)=>records[mode][k].push({name,amountMinor:Math.round(amount*10**CURRENCY_MINOR_UNITS[mode==='personal'?profileData.personalCurrency:profileData.businessCurrency]),currency:mode==='personal'?profileData.personalCurrency:profileData.businessCurrency,date:`${monthKey()}-${String(10+i).padStart(2,'0')}`,demo:true}))})}saveRecords();render()}
