let paypalEmbeddedReady=false;
let paypalEmbeddedInit=null;
let paypalSdkPromise=null;
let paypalCardFields=null;
let paypalCheckoutContext=null;
async function loadPayPalSdkV5(){
  if(window.paypal?.Buttons)return;
  if(paypalSdkPromise)return paypalSdkPromise;
  paypalSdkPromise=(async()=>{
    const cfg=await cloud.paypalPublicConfig();
    await new Promise((resolve,reject)=>{
      const sc=document.createElement('script');
      sc.src='https://www.paypal.com/sdk/js?client-id='+encodeURIComponent(cfg.clientId)+'&currency=USD&intent=capture&components=buttons,card-fields';
      sc.async=true;sc.dataset.paypalV5='1';
      sc.onload=resolve;sc.onerror=()=>{sc.remove();reject(new Error('No se pudo cargar el checkout seguro de PayPal.'))};
      document.head.appendChild(sc);
    });
    if(typeof window.paypal?.Buttons!=='function')throw new Error('PAYPAL_SDK_UNAVAILABLE');
  })();
  try{await paypalSdkPromise}catch(e){paypalSdkPromise=null;throw e}
}
function checkoutEmailValid(){
  const email=$('#checkoutEmail').value.trim().toLowerCase();
  if(!email||!email.includes('@')||!(email.split('@')[1]||'').includes('.')){
    $('#checkoutMsg').textContent='Escribe un correo electrónico válido.';
    $('#checkoutEmail').focus();return false;
  }
  return true;
}
function embeddedPaymentError(){
  if(sessionStorage.getItem('feo-checkout-recovery')){
    showCheckoutRecovery('Tu pago está pendiente de confirmación. No vuelvas a pagar; usa Reintentar confirmación.');
  }else $('#checkoutMsg').textContent='No pudimos completar el pago. Revisa los datos e inténtalo nuevamente.';
}
async function createEmbeddedOrder(){
  if(sessionStorage.getItem('feo-checkout-recovery')){embeddedPaymentError();throw new Error('PAYMENT_CONFIRMATION_PENDING')}
  if(!checkoutEmailValid())throw new Error('INVALID_EMAIL');
  const email=$('#checkoutEmail').value.trim().toLowerCase();
  $('#checkoutMsg').textContent='';
  if(paypalCheckoutContext?.email===email)return paypalCheckoutContext.order_id;
  const o=await cloud.createPublicCheckout(email);
  if(!o?.order_id||!o?.checkout_id||!o?.checkout_secret)throw new Error('CHECKOUT_UNAVAILABLE');
  o.email=email;
  paypalCheckoutContext=o;
  return o.order_id;
}
async function approveEmbeddedOrder(data){
  if(!paypalCheckoutContext||data.orderID!==paypalCheckoutContext.order_id)throw new Error('No encontramos el checkout activo.');
  const ctx={cid:paypalCheckoutContext.checkout_id,cs:paypalCheckoutContext.checkout_secret,token:data.orderID};
  sessionStorage.setItem('feo-checkout-recovery',JSON.stringify(ctx));
  try{
    const c=await cloud.capturePublicCheckout(ctx.cid,ctx.cs,ctx.token);
    if(!c?.claim_token)throw new Error('El pago se realizó, pero no pudimos preparar el acceso.');
    sessionStorage.removeItem('feo-checkout-recovery');
    paypalCheckoutContext=null;
    showPaidSignup(c.email,c.claim_token);
  }catch(e){
    showCheckoutRecovery('Tu pago puede estar aprobado, pero FINORVE todavía no pudo confirmar el acceso. No vuelvas a pagar; usa Reintentar confirmación.');
    throw e;
  }
}
async function initEmbeddedPayPal(){
  if(paypalEmbeddedReady)return;
  if(paypalEmbeddedInit)return paypalEmbeddedInit;
  paypalEmbeddedInit=(async()=>{
    const loading=$('#paypalCardLoading'),fields=$('#paypalCardFields'),unavailable=$('#paypalCardUnavailable');
    const walletLoading=$('#paypalButtonsLoading'),walletUnavailable=$('#paypalButtonsUnavailable');
    loading?.classList.remove('hidden');walletLoading?.classList.remove('hidden');
    unavailable?.classList.add('hidden');walletUnavailable?.classList.add('hidden');
    let walletReady=false,cardReady=false;
    try{
      await loadPayPalSdkV5();
      try{
        const buttons=window.paypal.Buttons({
          style:{layout:'vertical',color:'gold',shape:'rect',label:'pay'},
          fundingSource:window.paypal.FUNDING?.PAYPAL,
          createOrder:createEmbeddedOrder,onApprove:approveEmbeddedOrder,
          onClick:(_data,actions)=>checkoutEmailValid()?actions.resolve():actions.reject(),
          onCancel:()=>{paypalCheckoutContext=null;$('#checkoutMsg').textContent='Pago cancelado. Puedes intentarlo nuevamente.'},
          onError:embeddedPaymentError
        });
        if(!buttons.isEligible())throw new Error('PAYPAL_BUTTON_NOT_ELIGIBLE');
        await buttons.render('#paypal-buttons');walletReady=true;
      }catch{walletUnavailable?.classList.remove('hidden')}
      try{
        if(typeof window.paypal.CardFields!=='function')throw new Error('CARD_FIELDS_NOT_ELIGIBLE');
        const card=window.paypal.CardFields({createOrder:createEmbeddedOrder,onApprove:approveEmbeddedOrder,onError:embeddedPaymentError});
        if(!card.isEligible())throw new Error('CARD_FIELDS_NOT_ELIGIBLE');
        await card.NameField().render('#paypal-card-name');
        await card.NumberField().render('#paypal-card-number');
        await card.ExpiryField().render('#paypal-card-expiry');
        await card.CVVField().render('#paypal-card-cvv');
        paypalCardFields=card;fields?.classList.remove('hidden');cardReady=true;
      }catch{paypalCardFields=null;fields?.classList.add('hidden');unavailable?.classList.remove('hidden')}
      paypalEmbeddedReady=walletReady||cardReady;
    }catch{unavailable?.classList.remove('hidden');walletUnavailable?.classList.remove('hidden')}
    finally{
      loading?.classList.add('hidden');walletLoading?.classList.add('hidden');
      $('#retryPaymentMethods')?.classList.toggle('hidden',paypalEmbeddedReady);
    }
  })();
  try{await paypalEmbeddedInit}finally{paypalEmbeddedInit=null}
}
async function payEmbeddedCard(){
  const msg=$('#checkoutMsg'),btn=$('#payWithCard');msg.textContent='';
  if(!checkoutEmailValid())return;
  if(!paypalCardFields){msg.textContent='El pago con tarjeta todavía se está preparando.';return}
  btn.disabled=true;const old=btn.textContent;btn.textContent='Procesando pago…';
  try{await paypalCardFields.submit()}
  catch(e){embeddedPaymentError()}
  finally{btn.disabled=false;btn.textContent=old}
}
function bindAuthActions(){
  $('#payWithCard')?.addEventListener('click',payEmbeddedCard);
  $('#retryCheckoutCapture')?.addEventListener('click',retryCheckoutCapture);
  $('#retryPaymentMethods')?.addEventListener('click',()=>initEmbeddedPayPal());
  $('#existingLogin')?.addEventListener('click',()=>showExistingLogin());
  $('#paidExistingLogin')?.addEventListener('click',()=>showExistingLogin());
  $('#createPaidAccount')?.addEventListener('click',async()=>{
    const name=$('#paidName').value.trim(),email=$('#paidEmail').value.trim().toLowerCase(),password=$('#paidPassword').value,confirm=$('#paidPasswordConfirm').value,msg=$('#paidSignupMsg'),btn=$('#createPaidAccount'),claim=readPaidCheckout()?.claim;
    msg.textContent='';
    if(name.length<2){msg.textContent='Escribe tu nombre.';$('#paidName').focus();return}
    if(!validatePassword(password)){msg.textContent=PASSWORD_POLICY_MESSAGE;return}
    if(password!==confirm){msg.textContent='Las contraseñas no coinciden.';return}
    if(!claim){msg.textContent='El comprobante de pago ya no está disponible. Contacta soporte con tu recibo de PayPal.';return}
    btn.disabled=true;const old=btn.textContent;btn.textContent='Creando tu acceso…';
    try{
      await cloud.createPaidAccount(email,password,claim);
      await cloud.signIn(email,password);
      await cloud.saveProfile({name,country:'Ecuador',personalCurrency:'USD',businessCurrency:'USD',theme:'system',tutorialCompleted:false});
      clearPaidCheckout();
      await enterApp();
    }catch(e){
      if(e.message==='ACCOUNT_EXISTS'){
        const email=$('#paidEmail').value.trim().toLowerCase();
        showExistingLogin('✓ Compra verificada. Ya tienes una cuenta. Inicia sesión para activar tu acceso.');
        $('#authEmail').value=email;
        $('#authEmail').readOnly=true;
        $('#authPassword').focus();
      }else{
        msg.textContent=e.message;
      }
      btn.disabled=false;btn.textContent=old;
    }
  });
  $('#authSignin')?.addEventListener('click',()=>authMode==='recovery'?submitRecoveryPassword():window.feoAuth.submit('signin'));
  $('#authSignup')?.addEventListener('click',()=>showCheckout());
  $('#forgotPassword')?.addEventListener('click',()=>window.feoAuth.forgot());
  $('#accessLogout')?.addEventListener('click',()=>window.feoAuth.logout());
  $('#backToLogin')?.addEventListener('click',()=>location.reload());
  $('#resendConfirmation')?.addEventListener('click',async()=>{
    const btn=$('#resendConfirmation'), msg=$('#resendMsg'), email=$('#authCopy').textContent.match(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/)?.[0]||$('#authEmail').value.trim();
    btn.disabled=true; const old=btn.textContent; btn.textContent='Enviando…'; msg.textContent='';
    try{await cloud.resendSignupConfirmation(email);msg.textContent='Correo reenviado. Usa el enlace más reciente.'}catch(e){msg.textContent=authMessage(e)}finally{btn.disabled=false;btn.textContent=old}
  });
}
bindAuthActions();
function finishBoot(){const gate=$('#bootGate');if(!gate)return;gate.classList.add('bootDone');setTimeout(()=>gate.remove(),220)}
boot().finally(finishBoot);

function syncVisualViewport(){const vv=window.visualViewport;const h=vv?.height||window.innerHeight;document.documentElement.style.setProperty('--visual-viewport-height',h+'px');document.documentElement.dataset.keyboardOpen=vv&&window.innerHeight-h>120?'true':'false'}
syncVisualViewport();window.visualViewport?.addEventListener('resize',syncVisualViewport);window.visualViewport?.addEventListener('scroll',syncVisualViewport);document.addEventListener('focusin',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target?.tagName||''))setTimeout(()=>e.target.scrollIntoView({block:'center',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}),120)});


function personalFunds(){const goals=records.personal?.goal||[];return [...STANDARD_FUNDS.map(f=>({...f,config:goals.find(x=>x.fundId===f.id&&(!x.currency||x.currency===currency()))})),...goals.filter(x=>x.fundId&&!STANDARD_FUNDS.some(f=>f.id===x.fundId)&&(!x.currency||x.currency===currency())).map(x=>({id:x.fundId,name:x.name,help:'Tu objetivo personal de ahorro.',config:x}))]}
function greenFundChart(id){const points=fundHistory(records.personal?.saving,id,currency(),localDateKey());if(!points.length)return '<p class="sub">Tu gráfica aparecerá al registrar el primer aporte. No hay datos de ejemplo mezclados con tus ahorros.</p>';const target=asMinor(personalFunds().find(f=>f.id===id)?.config),max=Math.max(1,target,...points.map(x=>x.balance));const path=points.map((x,i)=>`${i?'L':'M'} ${points.length===1?160:12+i*296/(points.length-1)} ${110-x.balance*90/max}`).join(' ');const last=points.at(-1);const lastX=points.length===1?160:308;return `<svg class="fundChart" viewBox="0 0 320 130" role="img" aria-label="Evolución del ahorro: ${esc(points.map(x=>x.date+': '+moneyMinor(x.balance,currency())).join('; '))}">${target?`<line x1="12" x2="308" y1="${110-target*90/max}" y2="${110-target*90/max}" stroke="#9bb6a9" stroke-dasharray="4 4"/><text x="12" y="${Math.max(12,104-target*90/max)}" fill="#526a5c" font-size="10">Meta</text>`:''}<path d="${path} L ${lastX} 120 L ${points.length===1?160:12} 120 Z" fill="#e8f6ef"/><path d="${path}" fill="none" stroke="#318466" stroke-width="2.2" stroke-linejoin="round"/><circle cx="${lastX}" cy="${110-last.balance*90/max}" r="4" fill="#318466"/></svg><div class="fundChartDates"><span>${esc(points[0].date)}</span><span>${esc(last.date)}</span></div>`}
function homeFundChart(id){const points=fundHistory(records.personal?.saving,id,currency(),localDateKey());if(!points.length)return '<div class="fundHeroEmpty">Tu gráfica aparecerá con el primer aporte.</div>';const max=Math.max(1,...points.map(x=>x.balance)),firstDate=Date.parse(points[0].date+'T12:00:00Z'),lastDate=Date.parse(points.at(-1).date+'T12:00:00Z'),span=Math.max(1,lastDate-firstDate),xy=points.map(x=>({x:points.length===1?220:16+(Date.parse(x.date+'T12:00:00Z')-firstDate)*264/span,y:138-x.balance*100/max})),path=xy.map((x,i)=>`${i?'L':'M'} ${x.x} ${x.y}`).join(' '),last=xy.at(-1),previousMonthEnd=new Date(Date.UTC(Number(monthKey().slice(0,4)),Number(monthKey().slice(5,7))-1,0)).toISOString().slice(0,10),previous=fundBalance(records.personal?.saving,id,currency(),previousMonthEnd),change=previous>0?(points.at(-1).balance-previous)/previous*100:null,changeLabel=change===null?'Primeros aportes':`${change>0?'+':''}${new Intl.NumberFormat('es',{maximumFractionDigits:1}).format(change)} %`,label=change===null?'Primeros aportes registrados':`Cambio del saldo desde el cierre del mes anterior: ${changeLabel}`;return `<svg class="fundHeroChart" viewBox="0 0 300 180" role="img" aria-label="Evolución del ahorro: ${esc(points.map(x=>x.date+': '+moneyMinor(x.balance,currency())).join('; '))}"><path class="fundHeroArea" d="${path} L ${last.x} 180 L ${xy[0].x} 180 Z"/><path class="fundHeroLine" d="${path}"/><line class="fundHeroMarker" x1="${last.x}" x2="${last.x}" y1="${Math.max(0,last.y-34)}" y2="${last.y+34}"/><circle class="fundHeroDot" cx="${last.x}" cy="${last.y}" r="4.5"/></svg><span class="fundHeroChange ${change!==null&&change<0?'isNegative':''}" aria-label="${esc(label)}" title="${esc(label)}">${esc(changeLabel)}</span>`}
function survivalCard(compact=false){const fund=personalFunds().find(x=>x.id==='survival'),balance=fundBalance(records.personal?.saving,'survival',currency(),localDateKey()),s=survivalSummary(fund.config,balance);if(compact)return `<article class="card foundationSurvival fundHeroCompact"><div class="fundHeroCopy">${fundIcon('survival')}<h3>Supervivencia</h3><strong class="fundAmount">${moneyMinor(balance,currency())}</strong><p class="sub">${s.target?`${new Intl.NumberFormat('es',{maximumFractionDigits:1}).format(s.coverage)} de ${fund.config.targetMonths} meses esenciales cubiertos`:'Tu respaldo para cubrir al menos tres meses'}</p><button class="textAction" data-section="plan">${s.target?`${s.progress}% de tu meta · `:''}Ver mi base financiera <span aria-hidden="true">›</span></button></div><div class="fundHeroVisual">${homeFundChart('survival')}</div></article>`;return `<article class="card foundationSurvival">${fundIcon('survival')}<div class="cardHead"><div><span class="eyebrow">BASE FINANCIERA</span><h3>${compact?'Supervivencia':'Ahorro de supervivencia'}</h3></div><button class="ghost" data-foundation-config>Configurar</button></div><strong class="fundAmount">${moneyMinor(balance,currency())}</strong><p class="sub">${s.target?`${new Intl.NumberFormat('es',{minimumFractionDigits:1,maximumFractionDigits:1}).format(s.coverage)} meses cubiertos de ${fund.config.targetMonths}. Meta: ${moneyMinor(s.target,currency())}.`:'Define tus gastos esenciales mensuales y cuántos meses quieres cubrir: tres, seis o más.'}</p>${greenFundChart('survival')}${s.target?`<progress max="100" value="${s.progress}" aria-label="Avance del ahorro de supervivencia"></progress><p class="sub">${s.progress}% de la meta · ${s.remaining?`Faltan ${moneyMinor(s.remaining,currency())}`:'Meta alcanzada'}</p>`:''}<div class="foundationActions"><button class="primary" data-fund-add="survival">Añadir ahorro</button>${compact?'<button class="ghost" data-section="plan">Ver mi base financiera</button>':'<button class="ghost" data-fund-history="survival">Ver movimientos</button>'}</div></article>`}
function foundationView(){const funds=personalFunds();const unassigned=(records.personal?.saving||[]).filter(x=>!x.fundId).length;return `<div class="sectionHead"><div><h2>Base financiera</h2><p>Primero tu respaldo, después tus proyectos. Cada ahorro tiene su propio destino.</p></div><button class="primary" data-new-fund>Crear otro ahorro</button></div>${survivalCard()}<div class="foundationGrid">${funds.filter(f=>f.id!=='survival').map(f=>{const balance=fundBalance(records.personal?.saving,f.id,currency(),localDateKey());return `<article class="card fundCard" data-fund-card="${esc(f.id)}">${fundIcon(f.id)}<h3>${esc(f.name)}</h3><p class="sub">${esc(f.help)}</p><strong class="fundAmount">${moneyMinor(balance,currency())}</strong>${f.config?`<p class="sub">Meta: ${moneyMinor(asMinor(f.config),currency())} · Faltan ${moneyMinor(Math.max(0,asMinor(f.config)-balance),currency())}</p>`:''}${greenFundChart(f.id)}${f.config?`<button class="ghost" data-fund-edit="${esc(f.id)}">Editar meta</button>`:''}<div class="foundationActions"><button class="primary" data-fund-add="${esc(f.id)}">Añadir ahorro</button><button class="ghost" data-fund-history="${esc(f.id)}">Ver movimientos</button></div></article>`}).join('')}</div><div class="card foundationNote">${(records.personal.goal||[]).map((x,i)=>!x.fundId?`<div class="settingsRow"><div><b>${esc(x.name)}</b><small>Meta anterior: ${moneyMinor(asMinor(x),x.currency||currency())}</small></div><button class="ghost" data-adopt-goal="${i}">Usar como fondo</button></div>`:'').join('')}<h3>Un paso a la vez</h3><p>Construye al menos tres meses de supervivencia y aporta progresivamente a emergencia antes de dedicar más dinero al capital futuro. Puedes registrar tus objetivos desde ahora.</p>${unassigned?`<p>Tienes ${unassigned} movimientos de ahorro anteriores sin fondo asignado. Se conservan en tu historial; edítalos para elegir su destino.</p>`:''}<div class="foundationActions"><button class="ghost" data-section="savings">Todos mis movimientos de ahorro</button><button class="ghost" data-section="debts">Revisar deudas</button><button class="ghost" data-section="assets">Ver activos</button></div></div>`}
function fundPreview(f){const balance=fundBalance(records.personal?.saving,f.id,currency(),localDateKey());return `<button class="card fundPreview" data-section="plan">${fundIcon(f.id)}<h3>${esc(f.name)}</h3><strong>${moneyMinor(balance,currency())}</strong><p class="sub">${esc(f.id==='emergency'?'Para imprevistos':f.id==='future'?'Construye tu futuro':f.help)}</p><span class="srOnly">Abrir base financiera</span></button>`}
function personalHome(){const m=personalMonth(personalEngineData(),monthKey()),funds=personalFunds();return `<section class="card personalWelcome personalSummary" aria-label="Resumen del mes"><div class="personalBalance"><span class="sub">Disponible este mes</span><small class="homeMonth">${new Intl.DateTimeFormat('es',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(monthKey()+'-01T12:00:00Z'))}</small><div class="balanceAmount"><strong class="fundAmount">${moneyMinor(m.available,currency())}</strong><button class="balanceVisibility" data-toggle-amounts aria-label="${state.hideAmounts?'Mostrar':'Ocultar'} importes" aria-pressed="${!!state.hideAmounts}">${navIcon('visibility')}</button></div></div><div class="welcomeMetric"><span>Ingresos</span><strong>${moneyMinor(m.income,currency())}</strong></div><div class="welcomeMetric"><span>Gastos</span><strong>${moneyMinor(m.expense,currency())}</strong></div><div class="welcomeActions"><button class="primary" data-quick-expense>${navIcon('decisions')}Apuntar gasto</button><button class="secondary" data-quick-saving><span aria-hidden="true">＋</span>Añadir ahorro</button></div><p class="welcomeDetail">Disponible después de ahorro neto (${moneyMinor(m.netSavings,currency())}) y pagos de deuda (${moneyMinor(m.debtPayments,currency())}). <button class="textAction" data-quick-income>Añadir ingreso</button></p></section><div class="foundationHome personalHomePattern"><div class="homeFunds">${survivalCard(true)}<div class="homeFundGrid">${funds.filter(f=>['emergency','future'].includes(f.id)).map(fundPreview).join('')}</div></div><div class="homeOverview"><article class="card homeExpenses"><h3>Gastos del mes</h3>${expenseSummary()}<button class="textAction" data-section="expenses">Ver y apuntar gastos →</button></article><button class="card homeGuide" data-section="decisions"><span class="guideBadge">${navIcon('guide')}</span><span><b>Mi guía financiera</b><small>Revisa tus gastos y compara cómo afectan a tus metas.</small></span><i aria-hidden="true">›</i></button></div></div><section class="homePlan"><h3>Mi plan financiero</h3><div class="homePlanGrid">${quickAction('plan','','Base financiera','Construye una base sólida')}${quickAction('debts','','Deudas','Reduce y organiza')}${quickAction('plan','','Capital futuro','Prepara tus próximos proyectos')}${quickAction('assets','','Patrimonio','Revisa activos y deudas')}</div></section>`}
function expenseSummary(){const b=expenseBreakdown(records.personal?.expense,monthKey(),currency());return `<div class="list">${[...Object.entries(EXPENSE_TYPES).map(([key,x])=>[key,x.label]),['unclassified','Sin clasificar']].filter(([key])=>key!=='unclassified'||b[key]>0).map(([key,label])=>`<div class="metricRow"><span>${key==='unclassified'?navIcon('more'):navIcon(key==='fixed'?'fixed':key==='variable'?'variable':'ant')}${label}</span><b>${moneyMinor(b[key],currency())}</b></div>`).join('')}</div>`}
function expenseView(){const history=recordView();return `<div class="sectionHead"><div><h2>Mis gastos</h2><p>Apunta lo que acabas de gastar. Hoy es la fecha inicial; puedes cambiarla.</p></div><button class="primary" data-quick-expense>Apuntar gasto</button></div><div class="foundationGrid">${Object.entries(EXPENSE_TYPES).map(([key,x])=>`<article class="card"><h3>${x.label}</h3><p class="sub">${x.help}</p><button class="ghost" data-expense-type="${key}">Añadir gasto ${x.label.toLowerCase()}</button></article>`).join('')}</div><article class="card foundationNote"><h3>Este mes</h3>${expenseSummary()}</article>${history.slice(history.indexOf('<div class="recordSummary">'))}`}
function openPersonalMovement(type,index=null,fundId=null,expenseClass=null){const list=records.personal?.[type]||(records.personal[type]=[]),editing=Number.isInteger(index),current=editing?list[index]:null,isExpense=type==='expense',funds=personalFunds();if(current?.currency&&current.currency!==currency()){openModal('Moneda del movimiento','Este movimiento está en '+esc(current.currency)+'. Selecciona esa moneda en Perfil para editar sus gastos o fondos de ahorro. El importe original se conserva.');return}const selected=current?.expenseClass||expenseClass||[...list].reverse().find(x=>EXPENSE_TYPES[x.expenseClass])?.expenseClass||'variable';const selectedFund=current?.fundId||fundId||'survival';const choices=isExpense?`<div class="field"><label for="rExpenseClass">Tipo de gasto</label><select id="rExpenseClass">${Object.entries(EXPENSE_TYPES).map(([id,x])=>`<option value="${id}" ${selected===id?'selected':''}>${x.label}</option>`).join('')}${editing&&!current.expenseClass?'<option value="" selected>Sin clasificar · elige un tipo</option>':''}</select><small id="expenseHelp"></small></div>`:`<div class="field"><label for="rFund">¿Para qué ahorro?</label><select id="rFund">${funds.map(f=>`<option value="${esc(f.id)}" ${selectedFund===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}${editing&&!current.fundId?'<option value="" selected>Sin fondo asignado</option>':''}</select></div><div class="field"><label for="rDirection">Movimiento</label><select id="rDirection"><option value="deposit">Añadir ahorro</option><option value="withdrawal" ${isWithdrawal(current)?'selected':''}>Retirar ahorro</option></select></div>`;openModalForm(editing?'Editar movimiento':isExpense?'Apuntar gasto':'Añadir ahorro',`<div class="formGrid"><div class="field"><label for="rAmount">Importe (${esc(current?.currency||currency())})</label><input id="rAmount" inputmode="decimal" placeholder="${amountInput(0)}" aria-description="Usa el formato mostrado en el ejemplo, sin separadores de miles" value="${current?amountInput(asMinor(current),current.currency||'USD'):''}"></div>${choices}<div class="field"><label for="rName">Concepto</label><input id="rName" maxlength="80" list="personalConcepts" placeholder="${isExpense?'Elige un ejemplo o escribe el tuyo':'Ej. Aporte de este mes'}" value="${esc(current?.name||'')}"><datalist id="personalConcepts">${(isExpense?['Alquiler','Internet','Comida','Transporte','Ropa','Café','Snack','Otro']:['Aporte de este mes','Ahorro extra','Retirada para imprevisto']).map(x=>`<option value="${x}"></option>`).join('')}</datalist></div><div class="field"><label for="rDate">Fecha</label><input id="rDate" type="date" max="${localDateKey()}" value="${current?.date||localDateKey()}"></div></div>`,()=>{clearModalError();const amountMinor=toMinor($('#rAmount').value,current?.currency||currency()),name=$('#rName').value.trim(),date=$('#rDate').value;if(amountMinor===null||amountMinor<=0)return modalError('Escribe un importe válido mayor que cero.','#rAmount');if(name.length<2)return modalError('Elige un concepto o escribe uno de al menos dos caracteres.','#rName');if(!date||date>localDateKey())return modalError('Elige la fecha de un movimiento que ya ocurrió.','#rDate');const base={...current,name,amountMinor,date,currency:current?.currency||currency(),demo:current?.demo||false,entityType:type};if(isExpense){base.expenseClass=$('#rExpenseClass').value;if(!EXPENSE_TYPES[base.expenseClass])return modalError('Elige fijo, variable u hormiga.','#rExpenseClass')}else{base.fundId=$('#rFund').value;base.direction=$('#rDirection').value;if(!base.fundId)return modalError('Elige el fondo al que pertenece este ahorro.','#rFund');if(!withdrawalAllowed(list,base,base.currency,editing?index:null))return modalError('El saldo de ese fondo no alcanza. Revisa el importe y la fecha; no puede quedar negativo.','#rAmount')}if(editing)list[index]=base;else list.push(base);saveRecords();closeModal();render()});if(isExpense){const help=()=>$('#expenseHelp').textContent=EXPENSE_TYPES[$('#rExpenseClass').value]?.help||'Los gastos anteriores se conservan hasta que elijas su tipo.';$('#rExpenseClass').onchange=help;help()}}
function configureSurvival(){const f=personalFunds().find(x=>x.id==='survival');openModalForm('Tu ahorro de supervivencia',`<p>Incluye alquiler, servicios, alimentación básica y transporte necesario. Confirma cuánto necesitas cada mes.</p><div class="formGrid"><div class="field"><label for="baseMonthly">Gastos esenciales por mes (${esc(currency())})</label><input id="baseMonthly" inputmode="decimal" placeholder="${amountInput(0)}" aria-description="Usa el formato mostrado en el ejemplo, sin separadores de miles" value="${f.config?amountInput(f.config.essentialMonthlyMinor):''}"></div><div class="field"><label for="baseMonths">Meses que quieres cubrir</label><input id="baseMonths" type="number" min="3" max="60" step="1" value="${f.config?.targetMonths||3}"><small>Como mínimo tres meses. Puedes elegir seis o más.</small></div></div>`,()=>{clearModalError();const monthly=toMinor($('#baseMonthly').value),months=Number($('#baseMonths').value);if(!monthly||!Number.isSafeInteger(monthly))return modalError('Escribe tus gastos esenciales mensuales.','#baseMonthly');if(!Number.isInteger(months)||months<3||months>60||!Number.isSafeInteger(monthly*months))return modalError('Elige entre 3 y 60 meses completos.','#baseMonths');const list=records.personal.goal||(records.personal.goal=[]),i=list.findIndex(x=>x.fundId==='survival'&&(!x.currency||x.currency===currency()));const goal={...f.config,name:'Supervivencia',fundId:'survival',amountMinor:monthly*months,essentialMonthlyMinor:monthly,targetMonths:months,date:localDateKey(),currency:currency(),entityType:'goal',entityId:f.config?.entityId||crypto.randomUUID(),demo:f.config?.demo||false};if(i<0)list.push(goal);else list[i]=goal;saveRecords();closeModal();render()})}
function createPersonalFund(fundId=null,legacyIndex=null){const goals=records.personal.goal||(records.personal.goal=[]),index=Number.isInteger(legacyIndex)?legacyIndex:goals.findIndex(x=>x.fundId===fundId&&(!x.currency||x.currency===currency())),current=index>=0?goals[index]:null;openModalForm(current?'Editar ahorro':'Crear otro ahorro',`<p>Por ejemplo: vacaciones, formación o un proyecto personal.</p><div class="formGrid"><div class="field"><label for="fundName">Nombre de tu ahorro</label><input id="fundName" maxlength="80" placeholder="Ej. Vacaciones" value="${esc(current?.name||'')}"></div><div class="field"><label for="fundTarget">¿Cuánto quieres reunir? (${esc(current?.currency||currency())})</label><input id="fundTarget" inputmode="decimal" placeholder="${amountInput(0)}" aria-description="Usa el formato mostrado en el ejemplo, sin separadores de miles" value="${current?amountInput(asMinor(current),current.currency||'USD'):''}"></div></div>`,()=>{clearModalError();const name=$('#fundName').value.trim(),amountMinor=toMinor($('#fundTarget').value,current?.currency||currency());if(name.length<2)return modalError('Escribe un nombre de al menos dos caracteres.','#fundName');if(!amountMinor)return modalError('Escribe una meta mayor que cero.','#fundTarget');const id=current?.fundId||fundId||crypto.randomUUID(),goal={...current,name,amountMinor,date:current?.date||localDateKey(),currency:current?.currency||currency(),fundId:id,entityId:current?.entityId||id,entityType:'goal',demo:current?.demo||false};if(index>=0)goals[index]=goal;else goals.push(goal);saveRecords();closeModal();render()})}

function showFundHistory(id){const fund=personalFunds().find(f=>f.id===id);if(!fund)return;const rows=fundRows(records.personal.saving,id,currency(),localDateKey());openModal(esc(fund.name),rows.length?rows.map(x=>`${esc(x.date)} · ${esc(x.name)} · ${isWithdrawal(x)?'−':'+'}${moneyMinor(asMinor(x),x.currency||'USD')}`).join('<br>'):'Todavía no hay movimientos en este fondo. Puedes añadir el primer aporte.');}
function bindFoundation(){$$('[data-quick-income]').forEach(b=>b.onclick=()=>openRecordModal(null,'income'));$$('[data-fund-edit]').forEach(b=>b.onclick=()=>createPersonalFund(b.dataset.fundEdit));$$('[data-adopt-goal]').forEach(b=>b.onclick=()=>createPersonalFund(null,Number(b.dataset.adoptGoal)));$$('[data-quick-expense]').forEach(b=>b.onclick=()=>openPersonalMovement('expense'));$$('[data-expense-type]').forEach(b=>b.onclick=()=>openPersonalMovement('expense',null,null,b.dataset.expenseType));$$('[data-quick-saving]').forEach(b=>b.onclick=()=>openPersonalMovement('saving'));$$('[data-fund-add]').forEach(b=>b.onclick=()=>openPersonalMovement('saving',null,b.dataset.fundAdd));$$('[data-foundation-config]').forEach(b=>b.onclick=configureSurvival);$$('[data-new-fund]').forEach(b=>b.onclick=()=>createPersonalFund());$$('[data-fund-history]').forEach(b=>b.onclick=()=>showFundHistory(b.dataset.fundHistory));}

function renderBusinessHeader(){const header=$('#pageTitle')?.closest('header');if(!header)return;const active=state.mode==='business'&&state.section==='home';header.classList.toggle('businessHomeHeader',active);$('#pageTitle').parentElement.classList.add('headerTitle');if($('#pageEyebrow'))$('#pageEyebrow').hidden=active;let period=header.querySelector('.businessHeaderPeriod');if(!active){period?.remove();return}if(!period){period=document.createElement('div');period.className='businessHeaderPeriod';header.querySelector('.headActions').before(period)}const month=businessPeriod();period.innerHTML=`<label class="srOnly" for="businessPeriod">Mes del resumen</label><select id="businessPeriod">${businessMonths().map(m=>`<option value="${m}" ${m===month?'selected':''}>${esc(businessPeriodLabel(m))}</option>`).join('')}</select>`}
function businessMonths(){return businessPeriods(records.business||{},currency(),localDateKey())}
function businessPeriod(){return state.businessMonth||monthKey()}
function businessPeriodLabel(month){return new Intl.DateTimeFormat('es',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(month+'-01T12:00:00Z'))}
function businessCurrent(){return businessSummary(records.business||{},businessPeriod(),currency(),businessPeriodEnd(businessPeriod(),localDateKey()))}
function businessSalesChart(target){const points=businessSalesSeries(records.business||{},businessPeriod(),currency(),localDateKey()),total=points.at(-1)?.value||0,progress=target>0?Math.round(total/target*100):null;if(!points.length)return '<div class="fundHeroEmpty">La gráfica aparecerá al anotar las ventas de este período.</div>';const max=Math.max(1,target||0,total),first=Date.parse(points[0].date+'T12:00:00Z'),span=Math.max(1,Date.parse(points.at(-1).date+'T12:00:00Z')-first),xy=points.map(x=>({x:points.length===1?220:16+(Date.parse(x.date+'T12:00:00Z')-first)*264/span,y:138-x.value*100/max})),path=xy.map((x,i)=>`${i?'L':'M'} ${x.x} ${x.y}`).join(' '),last=xy.at(-1),targetY=138-(target||0)*100/max;return `<svg class="fundHeroChart businessIntegratedChart" viewBox="0 0 300 180" role="img" aria-label="Ventas acumuladas de ${esc(businessPeriodLabel(businessPeriod()))}: ${esc(moneyMinor(total,currency()))}${target===null?'':', punto de equilibrio '+esc(moneyMinor(target,currency()))}. ${points.length} ${points.length===1?'día de ventas registrado; la curva aparecerá al anotar más días':'días con ventas registradas'}">${target!==null?`<line class="equilibriumTarget" x1="16" x2="284" y1="${targetY}" y2="${targetY}"/><text x="16" y="${Math.max(14,targetY-8)}" font-size="10">Equilibrio</text>`:''}${points.length>1?`<path class="fundHeroArea" d="${path} L ${last.x} 180 L 16 180 Z"/><path class="fundHeroLine" d="${path}"/>`:''}<line class="fundHeroMarker" x1="${last.x}" x2="${last.x}" y1="${Math.max(0,last.y-26)}" y2="${last.y+26}"/><circle class="fundHeroDot" cx="${last.x}" cy="${last.y}" r="4.5"/></svg>${progress===null?'':`<span class="fundHeroChange equilibriumBadge" aria-label="Ventas como porcentaje del punto de equilibrio: ${new Intl.NumberFormat('es').format(progress)} %">${new Intl.NumberFormat('es').format(progress)} % del umbral</span>`}`}

function businessDashboard(){const s=businessCurrent(),month=businessPeriod(),label=businessPeriodLabel(month);return `<div class="card personalWelcome businessWelcome"><div><span class="eyebrow">CAJA AL ${businessPeriodEnd(month,localDateKey())}</span><h2>El dinero de tu negocio</h2><strong class="fundAmount">${s.cash===null?'Sin configurar':moneyMinor(s.cash,currency())}</strong><p class="sub">Saldo inicial más cobros, menos pagos registrados hasta esa fecha.</p></div><div class="foundationActions"><button class="primary" data-section="movements">Anotar el día</button><button class="ghost" data-business-config>Configurar negocio</button></div></div><div class="kpis businessKpis"><div class="kpi"><small>Vendido en el período</small><strong>${moneyMinor(s.sales,currency())}</strong></div><div class="kpi"><small>Cobrado por ventas</small><strong>${moneyMinor(s.collections,currency())}</strong></div><div class="kpi"><small>Resultado registrado</small><strong>${s.result===null?'Faltan datos':moneyMinor(s.result,currency())}</strong></div><div class="kpi"><small>Días anotados</small><strong>${s.registeredDays}</strong></div></div><div class="foundationHome businessHome"><article class="card foundationSurvival fundHeroCompact businessEquilibrium businessEquilibriumIntegrated"><div class="fundHeroCopy">${fundIcon('emergency')}<h3>Punto de equilibrio</h3><span class="equilibriumCaption">Necesitas vender al mes</span><strong class="fundAmount">${s.target===null?'Sin configurar':moneyMinor(s.target,currency())}</strong><p class="sub">Vendido: <b>${moneyMinor(s.sales,currency())}</b></p><p class="sub equilibriumCompactStatus">${s.target===null?'Define tus gastos fijos y margen.':s.remaining?`Faltan ${moneyMinor(s.remaining,currency())}`:'Umbral estimado alcanzado'}</p><button class="textAction" data-business-config aria-label="Ver cálculo del punto de equilibrio">Ver cálculo <span aria-hidden="true">›</span></button></div><div class="fundHeroVisual">${businessSalesChart(s.target)}</div><details class="equilibriumExplanation"><summary>Cómo interpretar esta gráfica</summary><p>${esc(label)} · Ventas acumuladas de los días registrados. ${s.target===null?'Configura tus gastos fijos y el margen de contribución para estimar el umbral.':`Cálculo con gastos fijos y margen configurados (${new Intl.NumberFormat('es',{maximumFractionDigits:1}).format(s.estimatedMargin/100)} %). ${s.remaining?'Todavía no has alcanzado el umbral.':`Ventas por encima del umbral: ${moneyMinor(Math.max(0,s.sales-s.target),currency())}.`} Ese importe no equivale íntegramente a ganancia.`} Los días sin anotar no se convierten en cero; con un solo día se muestra su punto y la curva aparece al registrar más días.</p></details></article><article class="card businessNext"><span class="guideBadge">${navIcon('guide')}</span><h3>Tu siguiente paso</h3><p>${!s.config?'Define tu caja inicial para que el saldo tenga un punto de partida.':s.result===null?'Añade el costo de lo vendido en los días anotados para calcular el resultado.':'Comprueba que registraste los cobros, costos y gastos del período antes de decidir con este resultado.'}</p><p class="sub">Los días sin anotar no significan cero. El resultado considera solo lo registrado y los impuestos que hayas incluido. El capital del préstamo se separa de los gastos.</p><button class="ghost" data-section="movements">Revisar mis días</button></article></div>`}

function businessDayView(){const date=state.businessDate||localDateKey(),d=readDaily(records.business||{},date,currency()),field=(key,label,help,required=false)=>`<div class="field"><label for="biz-${key}">${label} (${esc(currency())})</label><input id="biz-${key}" inputmode="decimal" placeholder="${required?'Escribe un importe o 0':'Opcional'}" value="${d.registered&&d[key]!==null?amountInput(d[key]):''}"><small>${help}</small></div>`;return `<div class="sectionHead"><div><h2>Anotar el día</h2><p>Guarda los totales de tu negocio. No necesitas registrar venta por venta.</p></div></div><article class="card"><div class="businessDayDate"><div class="field"><label for="bizDate">Fecha del día</label><input id="bizDate" type="date" max="${localDateKey()}" value="${esc(date)}"></div><button class="ghost" id="loadBusinessDay">Ver este día</button><span class="dayStatus">${d.registered?'Día guardado · puedes editarlo':'Día sin registrar'}</span></div><p class="sub">Guarda tus cambios antes de cargar otra fecha. Escribe cero cuando sabes que no hubo movimientos; un campo vacío no equivale a cero.</p><div class="formGrid businessDayFields">${field('collected','¿Cuánto cobraste hoy?','Todo el dinero recibido por ventas, incluso las de días anteriores.',true)}${field('purchases','Mercancía o materiales pagados','Dinero pagado por productos, materiales o empaques. Puede quedar mercancía para vender después.',true)}${field('expenses','Otros pagos del negocio','Por ejemplo alquiler, luz, publicidad o administración. No incluyas cuotas de deuda ni retiros del dueño.',true)}</div><details class="businessDetails"><summary>Vendí a crédito o cobré ventas anteriores</summary><div class="formGrid">${field('olderCollections','De lo cobrado, ¿cuánto era de ventas anteriores?','Este importe ya está incluido en lo cobrado hoy. No crea una venta nueva.')}${field('unpaidSales','Ventas de hoy pendientes de cobro','Lo vendido hoy que todavía no entró en caja.')}</div></details><details class="businessDetails"><summary>Calcular mi resultado: costo de lo vendido</summary>${field('soldCost','Costo de los productos o servicios vendidos hoy','El costo de lo que ya vendiste, aunque lo hayas comprado antes. Déjalo vacío si todavía no lo sabes; FINORVE no inventará la ganancia.')}</details><details class="businessDetails"><summary>Añadir otro movimiento</summary><div class="formGrid">${field('principal','Capital de deuda pagado','Reduce caja y deuda; no es un gasto operativo.')}${field('interest','Intereses pagados','Reduce caja y el resultado registrado.')}${field('loanReceived','Préstamo recibido','Aumenta caja; no se cuenta como una venta ni ganancia.')}${field('ownerContribution','Aporte del dueño','Dinero propio que pusiste en el negocio; no es una venta.')}${field('ownerWithdrawal','Retiro del dueño','Dinero que sacaste para ti; no es un costo ni gasto de la operación.')}</div></details><div id="businessDayError" class="modalMsg hidden" role="alert"></div><div class="foundationActions"><button class="primary" id="saveBusinessDay">${d.registered?'Guardar cambios del día':'Guardar día'}</button><button class="ghost" id="emptyBusinessDay">Hoy no hubo movimientos</button></div><p id="businessDaySaved" class="sub" role="status"></p></article><article class="card foundationNote"><h3>Días anteriores</h3><div class="list">${dailyList(records.business||{},currency()).slice(0,31).map(x=>`<div class="settingsRow"><div><b>${esc(x.date)}</b><small>Cobrado: ${moneyMinor(x.collected,currency())} · ${DAILY_FIELDS.some(k=>x[k]>0)?'Con movimientos':'Sin movimientos registrados'}</small></div><button class="ghost" data-edit-business-day="${esc(x.date)}">Ver día</button></div>`).join('')||'<p class="sub">Todavía no has anotado ningún día.</p>'}</div></article>`}
function businessOrganize(){return `<div class="sectionHead"><div><h2>Organizar</h2><p>Lo esencial primero. Las herramientas adicionales están disponibles cuando las necesites.</p></div></div><article class="card"><h3>La base de tu negocio</h3><p class="sub">Define el saldo inicial, la fecha y el cálculo estimado de equilibrio.</p><button class="primary" data-business-config>Configurar negocio</button></article><div class="moduleGrid foundationNote">${quickAction('cashflow','↕','Historial de caja','Revisa cobros, pagos, capital e intereses registrados.')}${quickAction('sales','＋','Ventas anteriores','Consulta los registros anteriores al resumen diario.')}${quickAction('costs','−','Costos registrados','El costo de lo vendido, separado de compras pagadas.')}${quickAction('expenses','▤','Gastos registrados','Revisa gastos operativos sin incluir retiros del dueño.')}</div><article class="card foundationNote"><h3>Costos y gastos, con claridad</h3><p class="sub">El costo de lo vendido corresponde a productos o servicios que ya vendiste. Los gastos mantienen el negocio funcionando, como alquiler, luz o publicidad. En Anotar el día puedes incluir pagos de deuda, aportes y retiros por separado.</p></article>`}
function configureBusiness(){const c=businessConfig(records.business||{},currency());openModalForm('La base de tu negocio',`<div class="formGrid"><div class="field"><label for="bizActivity">¿A qué se dedica tu negocio?</label><input id="bizActivity" maxlength="80" placeholder="Ej. Tienda o servicios" value="${esc(c?.activity||'')}"></div><div class="field"><label for="bizOpening">Caja y banco al empezar (${esc(currency())})</label><input id="bizOpening" inputmode="decimal" placeholder="${amountInput(0)}" aria-description="Usa el formato mostrado en el ejemplo, sin separadores de miles" value="${c?amountInput(c.openingCashMinor):''}"><small>Es el saldo al inicio de esa fecha, antes de sus movimientos. No es una venta.</small></div><div class="field"><label for="bizStart">Fecha del saldo inicial</label><input id="bizStart" type="date" max="${localDateKey()}" value="${esc(c?.startDate||localDateKey())}"></div><div class="field"><label for="bizFixed">Gastos fijos mensuales (${esc(currency())})</label><input id="bizFixed" inputmode="decimal" placeholder="Opcional" value="${c?.fixedMonthlyMinor!==undefined?amountInput(c.fixedMonthlyMinor):''}"><small>Alquiler, servicios fijos, administración. Esta configuración no crea pagos.</small></div><div class="field"><label for="bizMargin">Margen de contribución estimado (%)</label><input id="bizMargin" inputmode="decimal" placeholder="Opcional · Ej. 40" value="${c?.contributionMarginBp?amountInput(c.contributionMarginBp,'USD'):''}"><small>De cada 100 vendidos, cuánto queda después del costo variable de lo vendido. No es el porcentaje que sumas al costo para fijar un precio.</small></div></div>`,()=>{clearModalError();const opening=toMinor($('#bizOpening').value),start=$('#bizStart').value,fixed=$('#bizFixed').value.trim()?toMinor($('#bizFixed').value):null,margin=$('#bizMargin').value.trim()?toBasisPoints($('#bizMargin').value):null;if(opening===null)return modalError('Escribe un saldo inicial válido, incluso si es cero.','#bizOpening');if(!start||start>localDateKey())return modalError('Selecciona una fecha de inicio válida.','#bizStart');if(fixed===null&&$('#bizFixed').value.trim())return modalError('Revisa los gastos fijos.','#bizFixed');if(margin!==null&&(margin<=0||margin>10000)||margin===null&&$('#bizMargin').value.trim())return modalError('Escribe un porcentaje mayor que cero y de hasta 100.','#bizMargin');const b=records.business||(records.business={}),list=b.collection||(b.collection=[]),i=list.findIndex(x=>x.cashRole==='openingConfig'&&x.currency===currency()),row={...c,name:'Configuración de negocio',amountMinor:0,date:start,startDate:start,currency:currency(),cashRole:'openingConfig',openingCashMinor:opening,activity:$('#bizActivity').value.trim(),demo:false,entityType:'collection'};if(fixed!==null&&margin!==null){row.fixedMonthlyMinor=fixed;row.contributionMarginBp=margin}else{delete row.fixedMonthlyMinor;delete row.contributionMarginBp}if(i<0)list.push(row);else list[i]=row;saveRecords();closeModal();render()})}
function saveBusinessDay(){const error=$('#businessDayError');error.classList.add('hidden');try{const date=$('#bizDate').value;if(date!==(state.businessDate||localDateKey()))throw Error('Pulsa Ver este día para cargar esa fecha antes de guardar.');if(!date||date>localDateKey())throw Error('Elige un día que ya haya ocurrido.');const input={};for(const key of DAILY_FIELDS){const raw=$('#biz-'+key).value.trim();if(['collected','purchases','expenses'].includes(key)&&!raw)throw Error('Completa los tres importes principales. Escribe 0 si no hubo movimiento.');input[key]=key==='soldCost'&&!raw?null:raw?toMinor(raw):0}records.business=upsertDaily(records.business||{},date,currency(),input);saveRecords();render();$('#businessDaySaved').textContent='Día guardado en el dispositivo. La sincronización con tu cuenta sigue el estado indicado por FINORVE.'}catch(e){error.textContent=e.message;error.classList.remove('hidden')}}
function bindBusinessDaily(){$('#businessPeriod')?.addEventListener('change',e=>{state.businessMonth=e.target.value;render()});$$('[data-business-config]').forEach(b=>b.onclick=configureBusiness);$('#saveBusinessDay')?.addEventListener('click',saveBusinessDay);$('#loadBusinessDay')?.addEventListener('click',()=>{const date=$('#bizDate').value;if(!date||date>localDateKey()){const e=$('#businessDayError');e.textContent='Elige una fecha válida que ya haya ocurrido.';e.classList.remove('hidden');return}state.businessDate=date;render()});$$('[data-edit-business-day]').forEach(b=>b.onclick=()=>{state.businessDate=b.dataset.editBusinessDay;render()});$('#emptyBusinessDay')?.addEventListener('click',()=>{if(readDaily(records.business||{},state.businessDate||localDateKey(),currency()).registered){const e=$('#businessDayError');e.textContent='Este día ya está guardado. Revisa y edita sus importes antes de reemplazarlos por cero.';e.classList.remove('hidden');return}for(const key of DAILY_FIELDS)$('#biz-'+key).value='0';saveBusinessDay()})}


function calendarView(){const month=state.calendarMonth||monthKey(),date=state.calendarDate||localDateKey(),grid=monthDays(month),events=calendarAllEvents(),byDate=new Map();for(const x of events){if(!byDate.has(x.date))byDate.set(x.date,[]);byDate.get(x.date).push(x)}const selected=byDate.get(date)||[],caption=new Intl.DateTimeFormat('es',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(month+'-01T12:00:00Z'));return `<div class="sectionHead"><div><h2>Mi calendario</h2><p>${state.mode==='personal'?'Tus ingresos, gastos, ahorros y pagos de deuda.':'Tus cobros, pagos y resúmenes diarios del negocio.'} Lo previsto permanece separado de lo realizado.</p></div><button class="primary" data-new-reminder>Crear recordatorio</button></div><div class="calendarLayout"><article class="card"><div class="calendarMonth"><button class="ghost" data-calendar-shift="-1" aria-label="Mes anterior">‹</button><h3>${esc(caption)}</h3><button class="ghost" data-calendar-shift="1" aria-label="Mes siguiente">›</button></div><div class="calendarWeek" aria-hidden="true">${['L','M','X','J','V','S','D'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendarDays">${'<span class="calendarBlank"></span>'.repeat(grid.offset)}${grid.dates.map(day=>{const items=byDate.get(day)||[],cats=[...new Set(items.map(x=>x.category))].slice(0,4);return `<button class="calendarDay ${day===date?'selected':''} ${day===localDateKey()?'today':''}" data-calendar-date="${day}" aria-pressed="${day===date}" aria-label="${day}, ${items.length} ${items.length===1?'registro':'registros'}"><span>${Number(day.slice(-2))}</span><span class="calendarDots">${cats.map(cat=>`<i class="calendarDot ${cat}" aria-hidden="true"></i>`).join('')}</span></button>`}).join('')}</div><div class="calendarLegend"><span><i class="calendarDot income"></i>Entradas</span><span><i class="calendarDot expense"></i>Pagos / gastos</span><span><i class="calendarDot saving"></i>Ahorro</span><span><i class="calendarDot pending"></i>Pendiente</span></div></article><article class="card calendarDayList"><h3>${esc(new Intl.DateTimeFormat('es',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z')))}</h3><p class="sub">${selected.length?'Registros de este día':'No hay registros en este día. Esto no confirma que no hubiera movimientos.'}</p><div class="list">${selected.map(x=>`<div class="calendarEvent ${x.category}"><div><span class="calendarEventType">${esc(x.label)} · ${x.planned?'Pendiente':x.daily?'Guardado':'Registrado'}</span><b>${esc(x.name)}</b>${x.daily||x.membership?'':`<strong>${moneyMinor(x.amountMinor,currency())}</strong>`}${x.planned?'<small>Importe previsto; todavía no modifica tus saldos.</small>':''}</div><div class="calendarEventActions">${x.membership?'<a class="ghost" href="/renovar.html">Ver renovación</a>':x.planned?`<button class="primary" data-confirm-reminder="${esc(x.eventId)}">${['income','collection'].includes(x.eventType)?'Ya lo cobré':'Ya lo pagué / aporté'}</button><button class="ghost" data-edit-reminder="${esc(x.eventId)}">Editar aviso</button>`:x.dailyRecordId?`<button class="ghost" data-calendar-daily="${x.date}">Ver día</button>`:state.mode==='personal'&&['income','expense','saving'].includes(x.type)?`<button class="ghost" data-calendar-edit-type="${x.type}" data-calendar-index="${x.index}">Editar</button>`:''}</div></div>`).join('')}</div><div class="foundationActions"><button class="ghost" data-new-reminder>Recordar algo este día</button>${state.mode==='personal'?'<button class="ghost" data-quick-expense>Apuntar gasto de hoy</button>':`<button class="ghost" data-calendar-daily="${esc(date)}">Anotar / revisar este día</button>`}</div></article></div>${upcomingCard()}`}
function upcomingCard(){const list=upcomingEvents(bucket(),state.mode,currency(),localDateKey());return `<article class="card foundationNote"><div class="cardHead"><div><h3>Próximos siete días</h3><p class="sub">Solo avisos que has programado. No se descuentan del saldo.</p></div><button class="ghost" data-section="calendar">Ver calendario</button></div>${list.length?list.map(x=>`<div class="settingsRow"><div><b>${esc(x.name)}</b><small>${esc(x.date)} · ${esc(x.label)}</small></div><strong>${moneyMinor(x.amountMinor,currency())}</strong></div>`).join(''):'<p class="sub">No tienes avisos programados para estos días.</p>'}</article>`}
function openReminder(id=null){const reminders=bucket().reminder||(bucket().reminder=[]),current=id?reminders.find(x=>x.eventId===id):null,types=REMINDER_TYPES[state.mode],funds=state.mode==='personal'?personalFunds():[];openModalForm(current?'Editar recordatorio':'Crear recordatorio',`<div class="formGrid"><div class="field"><label for="calName">¿Qué quieres recordar?</label><input id="calName" maxlength="80" placeholder="Ej. Alquiler, cuota o cobro pendiente" value="${esc(current?.name||'')}"></div><div class="field"><label for="calDate">Fecha prevista</label><input id="calDate" type="date" value="${esc(current?.date||state.calendarDate||localDateKey())}"></div><div class="field"><label for="calType">Tipo de aviso</label><select id="calType">${Object.entries(types).map(([key,name])=>`<option value="${key}" ${(current?.eventType||(state.mode==='personal'?'expense':'cashPayment'))===key?'selected':''}>${name}</option>`).join('')}</select></div><div class="field"><label for="calAmount">Importe previsto (${esc(currency())})</label><input id="calAmount" inputmode="decimal" placeholder="${amountInput(0)}" aria-description="Usa el formato mostrado en el ejemplo, sin separadores de miles" value="${current?amountInput(current.plannedMinor,current.currency||currency()):''}"><small>Programarlo no cambia tus saldos.</small></div>${state.mode==='personal'?`<div class="field" id="calFundWrap"><label for="calFund">Fondo de ahorro</label><select id="calFund">${funds.map(f=>`<option value="${esc(f.id)}" ${current?.fundId===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div>`:''}</div>`,()=>{clearModalError();const name=$('#calName').value.trim(),date=$('#calDate').value,amount=toMinor($('#calAmount').value),type=$('#calType').value;if(name.length<2)return modalError('Escribe un concepto de al menos dos caracteres.','#calName');if(!validCalendarDate(date))return modalError('Elige una fecha válida.','#calDate');if(!amount)return modalError('Escribe un importe previsto mayor que cero.','#calAmount');const row={...current,name,date,amountMinor:0,plannedMinor:amount,currency:currency(),calendarRole:'reminder',eventId:current?.eventId||crypto.randomUUID(),eventType:type,entityType:'reminder',demo:false};if(type==='saving')row.fundId=$('#calFund').value;const i=current?reminders.findIndex(x=>x.eventId===id):-1;if(i>=0)reminders[i]=row;else reminders.push(row);saveRecords();closeModal();render()});if(state.mode==='personal'){const show=()=>$('#calFundWrap').classList.toggle('hidden',$('#calType').value!=='saving');$('#calType').onchange=show;show()}}
function confirmCalendarReminder(id){const current=(bucket().reminder||[]).find(x=>x.eventId===id);if(!current)return;openModalForm('Confirmar movimiento',`<p>Confirma lo que realmente ocurrió. FINORVE registrará este movimiento una sola vez.</p><div class="formGrid"><div class="field"><label for="calPaidAmount">Importe real (${esc(currency())})</label><input id="calPaidAmount" inputmode="decimal" value="${amountInput(current.plannedMinor,current.currency||currency())}"></div><div class="field"><label for="calPaidDate">Fecha real</label><input id="calPaidDate" type="date" max="${localDateKey()}" value="${localDateKey()}"></div></div>`,()=>{clearModalError();const amount=toMinor($('#calPaidAmount').value),date=$('#calPaidDate').value;if(!amount)return modalError('Escribe un importe real mayor que cero.','#calPaidAmount');if(!validCalendarDate(date)||date>localDateKey())return modalError('Elige la fecha en la que ocurrió.','#calPaidDate');try{records[state.mode]=confirmReminder(bucket(),id,state.mode,currency(),amount,date);saveRecords();state.calendarDate=date;state.calendarMonth=date.slice(0,7);closeModal();render()}catch(e){modalError(e.message,'#calPaidAmount')}})}
function bindCalendar(){$$('[data-calendar-date]').forEach(b=>b.onclick=()=>{state.calendarDate=b.dataset.calendarDate;render()});$$('[data-calendar-shift]').forEach(b=>b.onclick=()=>{const [y,m]=(state.calendarMonth||monthKey()).split('-').map(Number),d=new Date(Date.UTC(y,m-1+Number(b.dataset.calendarShift),1));state.calendarMonth=d.toISOString().slice(0,7);state.calendarDate=state.calendarMonth+'-01';render()});$$('[data-new-reminder]').forEach(b=>b.onclick=()=>openReminder());$$('[data-edit-reminder]').forEach(b=>b.onclick=()=>openReminder(b.dataset.editReminder));$$('[data-confirm-reminder]').forEach(b=>b.onclick=()=>confirmCalendarReminder(b.dataset.confirmReminder));$$('[data-calendar-daily]').forEach(b=>b.onclick=()=>{state.businessDate=b.dataset.calendarDaily;navigateApp({section:'movements',mode:'business'})});$$('[data-calendar-edit-type]').forEach(b=>b.onclick=()=>{const type=b.dataset.calendarEditType,index=Number(b.dataset.calendarIndex);if(['expense','saving'].includes(type))openPersonalMovement(type,index);else{navigateApp({section:'income',mode:'personal'});openRecordModal(index)}})}

function calendarAllEvents(){const events=calendarEvents(bucket(),state.mode,currency());if(membershipLicense?.expires_at){const d=new Date(membershipLicense.expires_at);if(!Number.isNaN(d.getTime())){const date=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Guayaquil',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);events.push({date,name:'Vencimiento de membresía anual',label:'Membresía',category:'pending',planned:false,membership:true,amountMinor:0})}}return events}

